import type { Lang } from './constants.js';

/**
 * "In 60 seconds" sentences (SPEC § 7.7), generated by template in both languages.
 * Inputs are already-sanitized strings from the database; the UI renders with textContent.
 */
type Localized = Record<Lang, string>;

const LOCALES: Record<Lang, string> = { en: 'en-US', fr: 'fr-FR' };

const compact = (value: number, lang: Lang) =>
  new Intl.NumberFormat(LOCALES[lang], { notation: 'compact', maximumFractionDigits: 1 }).format(
    value,
  );

const decimal = (value: number, lang: Lang) =>
  new Intl.NumberFormat(LOCALES[lang], {
    minimumFractionDigits: 1,
    maximumFractionDigits: 1,
  }).format(value);

const both = (render: (lang: Lang) => string): Localized => ({
  en: render('en'),
  fr: render('fr'),
});

export function sixtyKev(cveId: string, product: string | null): Localized {
  return both((lang) => {
    const what = product ? `${cveId} (${product})` : cveId;
    return lang === 'en'
      ? `CISA added ${what} to its exploited list: patch it first.`
      : `La CISA ajoute ${what} aux failles exploitées : à corriger en priorité.`;
  });
}

export function sixtyCritical(cveId: string, product: string | null, cvss: number): Localized {
  return both((lang) => {
    const where = product ?? (lang === 'en' ? 'your stack' : 'votre parc');
    return lang === 'en'
      ? `Critical flaw ${cveId} in ${where} (CVSS ${decimal(cvss, lang)}) hits your watchlist.`
      : `Faille critique ${cveId} dans ${where} (CVSS ${decimal(cvss, lang)}) : elle touche votre watchlist.`;
  });
}

export function sixtyBreach(title: string, accounts: number): Localized {
  return both((lang) =>
    lang === 'en'
      ? `${title}: ${compact(accounts, lang)} accounts exposed in a data breach.`
      : `${title} : ${compact(accounts, lang)} comptes exposés dans une fuite de données.`,
  );
}

export function sixtyRelease(product: string, version: string): Localized {
  return both((lang) =>
    lang === 'en'
      ? `${product} ${version} is a security release: upgrade.`
      : `${product} ${version} est une version de sécurité : mettez à jour.`,
  );
}

/** Articles stay in their original language (SPEC § 5): the headline is used as is. */
export function sixtyStory(title: string): Localized {
  return { en: title, fr: title };
}
